create table d_ref_option_deal_strike(key_otc_trade_id string comment '内部合约ID',seq string comment '序号',strike_pct string comment '执行价格（%）',strike string comment '执行价格',created_datetime string comment '创建时间',created_by string comment '创建人',updated_datetime string comment '修改时间',updated_by string comment '修改人',data_time string comment '【AI】数据时间',strike_delta_bps string comment '【AI】执行价格变动(基点)',belong_range string comment '【AI】所属区间') partitioned by (busi_date string) row format delimited fields terminated by ',' stored as textfile;
